function insertRange(ranges, newRange) {
  const result = []
  let [start, end] = newRange
  let i = 0
  while (i < ranges.length && ranges[i][1] < start) result.push([...ranges[i++]])
  while (i < ranges.length && ranges[i][0] <= end) {
    start = Math.min(start, ranges[i][0])
    end = Math.max(end, ranges[i][1])
    i++
  }
  result.push([start, end])
  while (i < ranges.length) result.push([...ranges[i++]])
  return result
}
